DROP POLICY "Professionals see compatible requests" ON public.service_requests;
CREATE POLICY "Professionals see compatible requests" ON public.service_requests FOR SELECT TO authenticated USING ((service_requests.status='open' AND EXISTS (SELECT 1 FROM public.professionals p WHERE p.user_id=auth.uid() AND public.matches_opportunity(p.id,service_requests.target_professional_id,service_requests.category_slug,service_requests.service_name,service_requests.city,service_requests.state,service_requests.neighborhood,service_requests.desired_date))) OR public.has_sent_quote(service_requests.id));